import AppKit
import Defaults

/// An installed app that can open a workroom directory, offered in the detail toolbar's
/// "Open in…" menu. Only the supported editors that are actually installed appear.
struct ExternalEditor: Identifiable {
  let id: String  // bundle identifier
  let name: String
  let appURL: URL

  /// Supported editors (bundle id + display name), in menu order.
  private static let supported: [(id: String, name: String)] = [
    ("com.microsoft.VSCode", "Visual Studio Code"),
    ("dev.zed.Zed", "Zed"),
    ("com.apple.dt.Xcode", "Xcode"),
  ]

  /// The supported editors currently installed, resolved to their app bundle URLs. **Cached** — see
  /// `EditorCache`: this is read straight from `OpenInControl.body`, which since issue #139 renders
  /// once per visible workroom pane, so the uncached version's three LaunchServices lookups per
  /// evaluation would run per pane on every pane rebuild (including every frame of a split-divider
  /// drag). The cache drops on app launch/terminate, so installing an editor still shows up live.
  static var installed: [ExternalEditor] {
    EditorCache.shared.editors {
      supported.compactMap { editor in
        guard let url = NSWorkspace.shared.urlForApplication(withBundleIdentifier: editor.id) else {
          return nil
        }
        return ExternalEditor(id: editor.id, name: editor.name, appURL: url)
      }
    }
  }

  /// The editor the primary "Open in" action uses: the one last picked (`Defaults[.lastEditor]`), else
  /// the first installed. nil when none are installed. Single source for the toolbar's open button, the
  /// ⌘O command, and the Go-menu item, so they always target the same editor.
  static var remembered: ExternalEditor? {
    let installed = installed
    return installed.first { $0.id == Defaults[.lastEditor] } ?? installed.first
  }

  /// The editor configured for opening *file paths* (Settings → "Open file paths in",
  /// `Defaults[.filePathEditor]`), or nil when unset — i.e. the file's default app. Names the
  /// Changes-panel "Open file in…" action (issue #93). Unlike `remembered`, this never falls back to
  /// the first installed editor: an unset/uninstalled choice deliberately reads as "default app".
  static var forFilePaths: ExternalEditor? {
    let id = Defaults[.filePathEditor]
    return id.isEmpty ? nil : installed.first { $0.id == id }
  }

  /// The app's Finder icon, sized for inline display beside its name in the
  /// "Open in…" button and menu. **Cached**, for the same reason `installed` is.
  ///
  /// Drawing into a fresh image rather than assigning `.size` on the returned one is load-bearing:
  /// `NSWorkspace.icon(forFile:)` may hand back an image from its own cache, so resizing it in place
  /// mutates shared state and every other caller silently gets a 20×20 icon.
  var icon: NSImage {
    EditorCache.shared.icon(for: id) {
      let source = NSWorkspace.shared.icon(forFile: appURL.path)
      return NSImage(size: NSSize(width: 20, height: 20), flipped: false) { rect in
        source.draw(in: rect)
        return true
      }
    }
  }

  /// Open `path` (a workroom directory) in this editor.
  func open(_ path: String) {
    NSWorkspace.shared.open(
      [URL(fileURLWithPath: path)],
      withApplicationAt: appURL,
      configuration: NSWorkspace.OpenConfiguration()
    )
  }
}

/// Memoizes the LaunchServices work behind `ExternalEditor.installed` / `.icon`, which are read from
/// SwiftUI view bodies — since issue #139 once per visible workroom pane, on every pane rebuild.
/// Uncached, one `OpenInControl` evaluation cost three `urlForApplication` lookups plus an
/// `icon(forFile:)`; a three-member split re-rendering per frame of a divider drag made that
/// hundreds of LaunchServices round-trips a second.
///
/// Invalidated when any app launches or quits, so installing (or deleting) an editor is picked up
/// without relaunching Workroom. Main-thread-confined in practice: every reader is a view body or a
/// menu builder, and the observers deliver on `.main`.
private final class EditorCache {
  static let shared = EditorCache()

  private var cachedEditors: [ExternalEditor]?
  private var cachedIcons: [String: NSImage] = [:]

  private init() {
    let center = NSWorkspace.shared.notificationCenter
    for name in [
      NSWorkspace.didLaunchApplicationNotification,
      NSWorkspace.didTerminateApplicationNotification,
    ] {
      center.addObserver(forName: name, object: nil, queue: .main) { [weak self] _ in
        self?.cachedEditors = nil
        self?.cachedIcons.removeAll()
      }
    }
  }

  func editors(_ resolve: () -> [ExternalEditor]) -> [ExternalEditor] {
    if let cachedEditors { return cachedEditors }
    let resolved = resolve()
    cachedEditors = resolved
    return resolved
  }

  func icon(for id: String, _ render: () -> NSImage) -> NSImage {
    if let cached = cachedIcons[id] { return cached }
    let rendered = render()
    cachedIcons[id] = rendered
    return rendered
  }
}

/// The "Open in…" editor control for a workroom: a menu whose primary action reopens in the
/// last-picked editor. A plain `View` (not `ToolbarContent`) so it composes into its host bar as a
/// sibling of the other controls, sharing its `.borderless` button style. (Renders nothing when no
/// editors are installed.)
///
/// Hosted in the **workroom pane title bar** (`WorkroomPaneTitleBar`) since issue #139 — it used to
/// sit in the window title bar keyed on the *selected* target, which left a co-displayed split
/// member's path unreachable. Now each visible workroom carries its own.
struct OpenInControl: View {
  let path: String

  /// Bundle id of the last editor picked from the "Open in…" menu — the primary action reopens in it.
  @Default(.lastEditor) private var lastEditorID

  var body: some View {
    let editors = ExternalEditor.installed
    if !editors.isEmpty {
      let remembered = editors.first { $0.id == lastEditorID } ?? editors[0]
      // Two SEPARATE controls in one tight group: an icon Button that opens in the remembered editor
      // on a single click (also ⇧⌘O / the Go-menu item), and a chevron Menu to pick a different one.
      // Both inherit the bar's `ToolbarIconButtonStyle`, so each gets its own hover well. Negative
      // spacing pulls the two 22pt-min wells together so the small chevron sits snug against the icon
      // (each well only paints on its own hover, so the slight overlap never shows two at once).
      HStack(spacing: -8) {
        Button {
          remembered.open(path)
        } label: {
          // Sized DIRECTLY, not by overlaying a hidden SF Symbol. That trick — a `.hidden()`
          // `arrow.up.forward.app` with the real icon in an `.overlay`, wrapped in a `.frame` — silently
          // ignored the frame: an overlay takes the size of the view it is attached to, and a bare Image
          // is fixed-size, so the icon rendered at whatever the ambient FONT made the hidden symbol
          // (~13pt) and the frame merely centred it in a larger box. Every attempt to resize it did
          // nothing. `.resizable().scaledToFit()` then a `.frame` sizes the icon itself.
          // `PaneToolbarIcon.appIcon`, not `.glyph` — see there for why the bitmap needs a bigger box
          // than the symbols to read the same size as them.
          Image(nsImage: remembered.icon)
            .renderingMode(.original)
            .resizable()
            .scaledToFit()
            .frame(width: PaneToolbarIcon.appIcon, height: PaneToolbarIcon.appIcon)
        }
        .help("Open in \(remembered.name) (⇧⌘O)")
        .accessibilityLabel("Open in \(remembered.name)")
        // A stable id beside the (editor-dependent) label, so a test can find this button without
        // knowing which editors the machine has installed — the reason it had no coverage before.
        .accessibilityIdentifier("openIn.primary")

        Menu {
          ForEach(editors) { editor in
            Button {
              lastEditorID = editor.id
              editor.open(path)
            } label: {
              Label {
                Text(editor.name)
              } icon: {
                Image(nsImage: editor.icon).renderingMode(.original)
              }
            }
          }
        } label: {
          Image(systemName: "chevron.down")
            .font(.system(size: PaneToolbarIcon.disclosure, weight: .semibold))
            .foregroundStyle(.secondary)
        }
        .menuStyle(.button)
        // We draw the chevron ourselves, so hide the system disclosure indicator.
        .menuIndicator(.hidden)
        .fixedSize()
        .help("Open in… (choose editor)")
        .accessibilityLabel("Choose editor")
        .accessibilityIdentifier("openIn.menu")
      }
    }
  }
}

/// The run-command controls for one workroom (issue #7): a Run button that becomes Restart + Stop
/// while the command is running. Reads run-state straight off `AppStore` — `@EnvironmentObject`
/// re-evaluates on `@Published` changes, so the toggle flips live (OV-A). A plain `View` (not

    let view = NSImageView()
    view.image = badgedIcon(text)
    tile.contentView = view
    tile.display()
  }

  /// The badge text for an unread count: `nil` clears the badge; the count is capped at "99+" to
  /// match the in-app `UnreadBadge` pill. Pure, so it's unit-testable.
  static func label(for count: Int) -> String? {
    guard count > 0 else { return nil }
    return count > 99 ? "99+" : "\(count)"
  }

  /// The app icon with a red badge (white, bold `text`) drawn in the top-right corner.
  private static func badgedIcon(_ text: String) -> NSImage {
    let side: CGFloat = 128
    let image = NSImage(size: NSSize(width: side, height: side))
    image.lockFocus()
    NSApp.applicationIconImage?.draw(in: NSRect(x: 0, y: 0, width: side, height: side))

    let attributes: [NSAttributedString.Key: Any] = [
      .foregroundColor: NSColor.white, .font: NSFont.boldSystemFont(ofSize: 30),
    ]
    let textSize = (text as NSString).size(withAttributes: attributes)
    let height: CGFloat = 46
    let width = max(height, textSize.width + 24)  // circle for 1–2 digits, capsule for "99+"
    let badge = NSRect(x: side - width - 2, y: side - height - 2, width: width, height: height)

    NSColor.systemRed.setFill()
    NSBezierPath(roundedRect: badge, xRadius: height / 2, yRadius: height / 2).fill()
    (text as NSString).draw(
      at: NSPoint(x: badge.midX - textSize.width / 2, y: badge.midY - textSize.height / 2),
      withAttributes: attributes)

    image.unlockFocus()
    return image
  }
}

import Foundation
import Sentry

/// Sentry SDK setup, kept out of `WorkroomApp.init()` so the app entry point stays readable.
///
/// macOS-trimmed option set: Workroom is macOS-only, so the iOS-only features in Sentry's
/// quick-start are deliberately left off — Session Replay, watchdog-termination tracking, and
/// screenshot/view-hierarchy attachment aren't supported on macOS. What remains is the coverage
/// that's valid here: crash reporting, app-hang detection, tracing, profiling, and metrics.
///
/// The DSN is a *public* client key (safe to embed — it only permits sending events, not reading
/// them), so it ships in the binary; `SENTRY_DSN` overrides it for local experiments. Structured
/// logs (`enableLogs`) are off: it wouldn't pick up the app's existing `os.Logger` calls anyway —
/// surfacing those would need explicit `SentrySDK.capture(...)` at the call sites (the `GhosttyApp`
/// terminal-startup failures being the prime candidates).
enum SentryConfig {
  /// Public ingest DSN. Overridable via `SENTRY_DSN` to point local runs at a different project.
  private static let dsn =
    "https://01c27f42380699d6072a6e30abe6e175@o272130.ingest.us.sentry.io/4511524517249024"

  static func start() {
    SentrySDK.start { options in
      options.dsn = ProcessInfo.processInfo.environment["SENTRY_DSN"] ?? dsn

      // Tag dev builds so local crashes/traces don't pollute the production environment in Sentry.
      // `SENTRY_ENVIRONMENT` overrides either default.
      options.environment =
        ProcessInfo.processInfo.environment["SENTRY_ENVIRONMENT"] ?? defaultEnvironment()
      // releaseName defaults to "<bundle id>@<version>+<build>", which release.sh already drives.

      // Error monitoring: crashes + app hangs. Watchdog-termination tracking and the
      // non-fully-blocking app-hang report (`enableReportNonFullyBlockingAppHangs`) are both
      // iOS/tvOS/visionOS-only — unavailable on macOS — so they're left out entirely.
      options.enableCrashHandler = true
      options.enableAppHangTracking = true

      // Don't attach PII (IP address / user context). The SDK default, restated for intent: a local
      // dev tool gains little from it, and it keeps user-identifying data out of events.
      options.sendDefaultPii = false

      // Tracing — auto-instruments app launch, network, and SwiftUI. A desktop app sees low
      // transaction volume, so full sampling is affordable; lower this if that ever changes.
      options.tracesSampleRate = 1.0

      // Profiling (macOS-supported). `.trace` lifecycle ties profiles to sampled transactions.
      options.configureProfiling = {
        $0.sessionSampleRate = 1.0
        $0.lifecycle = .trace
      }

      // Metrics are on by default in SDK 9.12+; explicit for intent.
      options.enableMetrics = true
    }
  }

  /// The Sentry `environment` for this build: `development` for Debug, `nightly` for the side-by-side
  /// Workroom Nightly product, `production` for the shipping app.
  ///
  /// Nightly needs its own environment, not just its own release name. The `Nightly` build config is
  /// release-type (no `DEBUG`), so nightly events used to arrive tagged `production` — which is how
  /// WORKROOM-2B, an App Hang from a build that ships from the tip of `master` to a handful of people,
  /// was indistinguishable from a hang in the released app. Alert rules and saved searches scoped to
  /// `environment:production` will stop matching nightly events, which is the point.
  ///
  /// Both parameters default to the real build facts and exist purely so `SentryConfigTests` never has
  /// to fake a build configuration (the same seam `UITestFixture` uses).
  static func defaultEnvironment(
    nightly: Bool = ReleaseChannel.isNightlyBuild, debug: Bool = isDebugBuild
  ) -> String {
    if debug { return "development" }
    return nightly ? "nightly" : "production"
  }

  /// Whether this is a Debug build. A stored fact rather than an `#if` at the use site so
  /// `defaultEnvironment` stays a pure function of its inputs.
  static let isDebugBuild: Bool = {
    #if DEBUG
      return true
    #else
      return false
    #endif
  }()
}

